package com.cicli.esempio;

public class CicloWhile {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int n1 = 0;
		int n2 = 10;
		
		while (n1<=n2) {
			System.out.println(n1);
			n1++;
		}
		
	}

}




